/**
 * Expo config plugin: declares `android:supportsRtl="true"` on <application> (TASK-024).
 *
 * Why: Arabic is a right-to-left app language. The generated manifest has no supportsRtl
 * attribute, and without it Android resolves every layout as left-to-right no matter what
 * `I18nManager.forceRTL(true)` says. The android/ folder is regenerated by `expo prebuild`,
 * so this plugin re-applies the attribute on every prebuild.
 */
const { withAndroidManifest, AndroidConfig } = require('expo/config-plugins');

/** Sets the attribute on the manifest's <application> element (object form from xml2js). */
function setSupportsRtl(application) {
  application.$['android:supportsRtl'] = 'true';
  return application;
}

function withRtlSupport(config) {
  return withAndroidManifest(config, (cfg) => {
    setSupportsRtl(AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults));
    return cfg;
  });
}

module.exports = withRtlSupport;
module.exports.setSupportsRtl = setSupportsRtl;
